export const METRICS={systolic_bp:{label:'Systolic blood pressure',short:'Blood pressure',unit:'mmHg',min:50,max:260},diastolic_bp:{label:'Diastolic blood pressure',short:'Diastolic BP',unit:'mmHg',min:30,max:180},ldl:{label:'LDL cholesterol',short:'LDL cholesterol',unit:'mg/dL',min:1,max:600},hdl:{label:'HDL cholesterol',short:'HDL cholesterol',unit:'mg/dL',min:1,max:200},bmi:{label:'Body mass index',short:'BMI',unit:'kg/m²',min:10,max:80},weight:{label:'Weight',short:'Weight',unit:'kg',min:20,max:350},hba1c:{label:'HbA1c',short:'HbA1c',unit:'%',min:2,max:25},heart_rate:{label:'Resting heart rate',short:'Heart rate',unit:'bpm',min:25,max:240},total_cholesterol:{label:'Total cholesterol',short:'Total cholesterol',unit:'mg/dL',min:1,max:700},triglycerides:{label:'Triglycerides',short:'Triglycerides',unit:'mg/dL',min:1,max:3000},glucose:{label:'Blood glucose',short:'Glucose',unit:'mg/dL',min:20,max:1000},creatinine:{label:'Creatinine',short:'Creatinine',unit:'mg/dL',min:.1,max:30},egfr:{label:'eGFR',short:'eGFR',unit:'mL/min/1.73m²',min:1,max:200},uacr:{label:'UACR',short:'UACR',unit:'mg/g',min:0,max:10000}};
const localNow=new Date();
export const TODAY=`${localNow.getFullYear()}-${String(localNow.getMonth()+1).padStart(2,'0')}-${String(localNow.getDate()).padStart(2,'0')}`;
export function numeric(v){if(!['number','string'].includes(typeof v)||String(v).trim()===''||String(v).trim().toLowerCase()==='unknown')return null;const n=Number(v);return Number.isFinite(n)?n:null;}
export function bmi(height,weight){const h=numeric(height),w=numeric(weight);return h>0&&w>0?Math.round(w/((h/100)**2)*10)/10:null;}
export function emergency(symptoms){return Boolean(symptoms.severe_chest_pain||symptoms.severe_breathlessness||symptoms.fainting);}
export function validDate(date){return typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(Date.parse(date))&&new Date(date).toISOString().slice(0,10)===date&&date<=TODAY;}
export function validateMeasurement(m){if(!m||!Object.hasOwn(METRICS,m.type))throw new Error('Unsupported measurement type.');const spec=METRICS[m.type];const value=numeric(m.value);if(value===null)throw new Error('Enter a measurement or leave it unknown.');if(value<spec.min||value>spec.max)throw new Error(`${spec.label} must be between ${spec.min} and ${spec.max} ${spec.unit}.`);if(m.unit!==spec.unit)throw new Error(`Use ${spec.unit} for ${spec.label}; unit conversion is not available.`);if(!validDate(m.recorded_at))throw new Error(`Use a valid date on or before ${TODAY}.`);return {...m,value,verified:false};}
export function validateBloodPressure(records){const dates=new Map();for(const r of records){if(!['systolic_bp','diastolic_bp'].includes(r.type))continue;const values=dates.get(r.recorded_at)||{};values[r.type]=numeric(r.value);dates.set(r.recorded_at,values);}for(const [date,v] of dates){if(v.systolic_bp!==undefined&&v.diastolic_bp!==undefined&&v.systolic_bp<=v.diastolic_bp)throw new Error(`Systolic BP must be higher than diastolic BP on ${date}.`);}return records;}
export function trend(records,type,years=3){const dates=new Map();for(const r of records){if(r.type===type&&numeric(r.value)!==null&&validDate(r.recorded_at))dates.set(r.recorded_at,r);}const r=[...dates.values()].sort((a,b)=>a.recorded_at.localeCompare(b.recorded_at));if(r.length<2)return null;const latest=r.at(-1);const cutoff=new Date(latest.recorded_at+'T00:00:00Z');cutoff.setUTCFullYear(cutoff.getUTCFullYear()-years);const target=cutoff.toISOString().slice(0,10);const base=r.filter(x=>x.recorded_at<=target).at(-1)||r[0];const days=Math.round((Date.parse(latest.recorded_at)-Date.parse(base.recorded_at))/86400000);const elapsed=Math.round(days/365.25*10)/10;const period_label=days<60?`${days} ${days===1?'day':'days'}`:days<365?`${Math.round(days/30.44)} months`:`${elapsed} ${elapsed===1?'year':'years'}`;return {latest,base,change:Math.round((latest.value-base.value)*10)/10,years:elapsed,days,period_label};}
export function preliminaryEligibility(profile){const age=numeric(profile.age);if(age===null)return {eligible:false,reason:'Age is required to screen calculator eligibility.'};if(age<30||age>79)return {eligible:false,reason:'PREVENT 10-year equations apply to adults aged 30–79.'};if(profile.previous_heart_disease||profile.previous_stroke||profile.heart_failure||profile.previous_heart_attack)return {eligible:false,reason:'Known cardiovascular disease falls outside the primary-prevention population.'};return {eligible:true,reason:'Age and reported history pass an initial screen. Full input and population checks are still required.'};}
function csvRows(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV contains an unclosed quotation mark.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
export function parseCSV(text){const rows=csvRows(text.replace(/^\uFEFF/,''));const headers=rows.shift()?.map(x=>x.trim().toLowerCase())||[];if(headers.some(h=>!h)||new Set(headers).size!==headers.length)throw new Error('CSV headers must be unique and non-empty.');for(const required of ['type','value','unit','recorded_at'])if(!headers.includes(required))throw new Error(`CSV needs a ${required} column.`);if(rows.length>500)throw new Error('Import up to 500 measurements at a time.');if(!rows.length)throw new Error('No measurements were found.');const records=rows.map((row,i)=>{if(row.length!==headers.length)throw new Error(`Row ${i+2}: column count does not match the header.`);const obj=Object.fromEntries(headers.map((h,j)=>[h,row[j]?.trim()||'']));obj.type=obj.type.toLowerCase();try{return validateMeasurement({...obj,source:'csv',verified:false});}catch(e){throw new Error(`Row ${i+2}: ${e.message}`);}});return validateBloodPressure(records);}
export function parseFHIR(data){if(!data||typeof data!=='object')throw new Error('Choose a FHIR Observation or Bundle JSON document.');if(data.resourceType==='Bundle'&&data.entry!==undefined&&!Array.isArray(data.entry))throw new Error('FHIR Bundle entry must be an array.');const codeMap={'2089-1':'ldl','13457-7':'ldl','2085-9':'hdl','2093-3':'total_cholesterol','2571-8':'triglycerides','4548-4':'hba1c','8480-6':'systolic_bp','8462-4':'diastolic_bp','8867-4':'heart_rate','29463-7':'weight','39156-5':'bmi'};const observations=data.resourceType==='Bundle'?(data.entry||[]).map(e=>e?.resource):[data];const values=[];for(const o of observations){if(o?.resourceType!=='Observation')continue;if(['entered-in-error','cancelled'].includes(o.status))throw new Error('Observations cancelled or entered in error cannot be imported.');const date=(o.effectiveDateTime||o.effectivePeriod?.start||'').slice(0,10);if(o.component!==undefined&&!Array.isArray(o.component))throw new Error('FHIR Observation component must be an array.');for(const part of [o,...(o.component||[])]){const coding=Array.isArray(part?.code?.coding)?part.code.coding.find(c=>c?.system==='http://loinc.org'&&Object.hasOwn(codeMap,c.code)):null;if(!coding||!part.valueQuantity)continue;const type=codeMap[coding.code];const q=part.valueQuantity;if(q.comparator)throw new Error('Inequality-valued observations require manual review; enter an exact measurement or keep it unknown.');const unit=q.system==='http://unitsofmeasure.org'&&q.code?q.code:q.unit||q.code;const normalized=({'kg/m2':'kg/m²','mm[Hg]':'mmHg'})[unit]||unit;values.push(validateMeasurement({type,value:q.value,unit:normalized,recorded_at:date,source:'fhir',verified:false}));}}if(!values.length)throw new Error('No supported LOINC-coded measurements were found.');if(values.length>500)throw new Error('Import up to 500 measurements at a time.');return validateBloodPressure(values);}
